from engine import span
def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='Carlos I de España y V del Sacro Imperio Romano Germánico reunió por primera vez en una misma persona las coronas de Castilla y Aragón y, a la vez, el patrimonio de los Habsburgo. Este capítulo explica cómo heredó sus dominios, qué fue la guerra de las Comunidades, qué guerras sostuvo y cómo las financió, y por qué su herencia se dividió en 1556.',
        quotes=[Q('es_carlos1','reuniendo así por primera vez en una misma persona, de forma efectiva, las coronas de Castilla y Aragón'), Q('en_carlos5','He was heir to and then head of the rising House of Habsburg.')]))
    P.append(dict(text='Carlos nació en Gante el 24 de febrero de 1500, hijo de Juana de Castilla y de Felipe el Hermoso, y nieto por vía materna de los Reyes Católicos y por vía paterna del emperador Maximiliano I. Tras la muerte de su padre en 1506 heredó los Países Bajos borgoñones; en 1516 se convirtió en rey de España junto con su madre, Juana, que desde 1506 no ejercía ningún poder efectivo. Con la muerte de Maximiliano en 1519 heredó los territorios hereditarios de Austria y fue elegido emperador.',
        quotes=[Q('es_carlos1','Gante, 24 de febrero de 1500','Cuacos de Yuste, 21 de septiembre de 1558'), Q('en_carlos5','After his father\'s death in 1506, he inherited the Habsburg Netherlands in the Low Countries.','In 1516, he became King of Spain as co-monarch of Castile and Aragon with his mother.'), Q('es_carlos1','desde 1506 no ejerció ningún poder efectivo')]))
    P.append(dict(text='Las fechas de su título imperial difieren entre las fuentes y conviene entender por qué. Una dice que fue emperador de 1520 a 1558; otra, que lo fue de 1519 a 1556. Las fuentes no explican la divergencia, pero es compatible con que la elección (1519), la coronación y la abdicación de 1556 sean momentos distintos de un mismo proceso; la fecha de su muerte, 1558, es la que sí coincide en las dos.',
        quotes=[Q('es_carlos1','Fue emperador del Sacro Imperio Romano Germánico como Carlos V de 1520 a 1558.'), Q('en_carlos5','Holy Roman Emperor and Archduke of Austria from 1519 to 1556'), Q('en_carlos5','Crowned King of Germany in Aachen'), Q('en_carlos5','In 1557, Charles retired to the Monastery of Yuste in Extremadura and died there a year later.')]))
    P.append(dict(text='El joven rey llegó a Asturias en octubre de 1517 sin apenas saber castellano y acompañado de un gran número de nobles y clérigos flamencos, lo que despertó recelos entre las élites castellanas, que temieron perder poder y estatus. A las Cortes de Valladolid de 1518 llegó sin saber hablar apenas castellano, y ese recelo pasó después a las capas populares. Las demandas fiscales que acompañaron su marcha a Alemania para la elección imperial en 1520 detonaron una serie de revueltas urbanas.',
        quotes=[Q('es_comunidades','En octubre de 1517, el rey Carlos I llegó a Asturias proveniente de Flandes'), Q('en_comuneros','He arrived in Spain in October 1517 accompanied by a large retinue of Flemish nobles and clerics.'), Q('es_comunidades','A las Cortes de Valladolid de 1518 llegó sin saber hablar apenas castellano'), Q('es_comunidades','Las demandas fiscales, coincidentes con la salida del rey para la elección imperial en Alemania tras las Cortes de Santiago y La Coruña de 1520, produjeron una serie de revueltas urbanas')]))
    P.append(dict(text='Las ciudades sublevadas, con Toledo, Segovia y Valladolid a la cabeza, buscaron una candidata alternativa en la reina Juana, a la que se esperaba poder controlar por su supuesta incapacidad. La Junta de Ávila redactó la llamada Ley Perpetua, que una de las fuentes describe como el primer proyecto de constitución política en la historia de España, aunque nunca llegó a firmarse. Pasado casi un año, los partidarios del emperador, sobre todo la alta nobleza, se reorganizaron y derrotaron a los comuneros en Villalar el 23 de abril de 1521. Al día siguiente se decapitó a Padilla, Bravo y Maldonado.',
        quotes=[Q('es_comunidades','encontrando un candidato alternativo a la corona en la «reina propietaria de Castilla», la madre de Carlos, Juana'), Q('en_comuneros','On 23 April 1521, after nearly a year of rebellion, the reorganized supporters of the emperor struck a crippling blow to the comuneros at the Battle of Villalar.'), Q('es_comunidades','Allí mismo, al día siguiente, se decapitó a los líderes comuneros: Padilla, Bravo y Maldonado.'), Q('es_comunidades','Ley Perpetua, primer proyecto de constitución política en la historia de España, que nunca llegó a ser firmad')]))
    P.append(dict(text='Las fuentes no coinciden en cuándo se rindió Toledo, el último foco de resistencia. Una dice que fue el 3 de febrero de 1522, casi un año después de Villalar; la otra, en octubre de 1521. La diferencia de cuatro meses es un buen ejemplo de por qué no se debe tomar como definitiva una sola fecha de enciclopedia: las dos describen el mismo hecho, la capitulación de la ciudad que dirigía María Pacheco, y las fuentes no explican la discrepancia.',
        quotes=[Q('es_comunidades','hasta su rendición definitiva casi un año después, el 3 de febrero de 1522'), Q('en_comuneros','until its surrender in October 1521'), Q('en_comuneros','Only the city of Toledo kept alive the rebellion led by María Pacheco')]))
    P.append(dict(text='El carácter de la revuelta es discutido. Algunos estudiosos la califican de revuelta antiseñorial y otros, de una de las primeras revoluciones de la Edad Moderna, por su rechazo a la injusticia social y por sus ideales de libertad. Una tercera lectura la ve como un movimiento antifiscal y particularista, de índole medievalizante, y otra, como una rebelión típica contra los altos impuestos y el control extranjero. Estas lecturas no se excluyen del todo, pero muestran que un mismo hecho admite varias interpretaciones.',
        quotes=[Q('es_comunidades','algunos estudiosos califican las Comunidades como una revuelta antiseñorial','de índole medievalizante'), Q('en_comuneros','According to some scholars, the revolt was one of the first modern revolutions'), Q('en_comuneros','Others consider it a more typical rebellion against high taxes and perceived foreign control.')]))
    P.append(dict(text='Carlos pasó gran parte de su vida en guerra. En 1521 Francisco I de Francia, rodeado por los territorios de los Habsburgo, inició una guerra en Italia que lo llevó a ser capturado en la batalla de Pavía, en 1525. En 1527 un ejército de soldados amotinados del emperador saqueó Roma. Después, Carlos defendió Viena de los turcos y fue coronado rey de Italia y emperador por el papa Clemente VII; en 1535 tomó posesión de Milán y capturó Túnez.',
        quotes=[Q('es_carlos1','En 1521 Francisco I de Francia, rodeado por las posesiones de los Habsburgo, inició una guerra en Italia que lo llevó a su captura en la batalla de Pavía (1525).'), Q('en_carlos5','In 1527, Rome was sacked by an army of Charles\'s mutinous soldiers.'), Q('es_carlos1','En 1535, tomó posesión de Milán y capturó Túnez.')]))
    P.append(dict(text='Aunque su imperio le llegó pacíficamente, Carlos pasó la mayor parte de su vida librando guerras, agotando sus ingresos y dejando deudas. Pidió dinero prestado a banqueros alemanes e italianos y, para devolverlo, dependió de la riqueza de los Países Bajos y del flujo de plata de Nueva España y Perú. Las dos fuentes añaden una consecuencia económica: la llegada de plata provocó una inflación generalizada.',
        quotes=[Q('es_carlos1','Aunque su imperio le llegó pacíficamente, pasó la mayor parte de su vida librando guerras, agotando sus ingresos y dejando deudas'), Q('en_carlos5','Charles borrowed money from German and Italian bankers and, to repay them, relied on the wealth of the Low Countries and the flow of silver from New Spain and Peru'), Q('es_carlos1','lo que provocó una inflación generalizada')]))
    P.append(dict(text='El emperador no tuvo capital fija. Realizó cuarenta viajes por los distintos territorios que gobernaba y dedicó una cuarta parte de su reinado a viajar dentro de sus reinos. Cuando salió hacia Alemania en 1520 dejó el gobierno de Castilla al cardenal Adriano de Utrecht.',
        quotes=[Q('es_carlos1','Sin fijar una capital, realizó 40 viajes por las diferentes entidades que gobernaba y dedicó una cuarta parte de su reinado a viajar dentro de sus reinos.'), Q('en_carlos5','With no fixed capital, he made 40 journeys through the different entities he ruled and spent a quarter of his reign travelling within his realms.'), Q('en_comuneros','leaving the Dutch cardinal Adrian of Utrecht to rule Castile in his absence')]))
    P.append(dict(role='definition', text='Monarquía universal: concepto medieval que Carlos revitalizó. Su dominio reunió territorios europeos y americanos y fue el primer conjunto de reinos al que se llamó «el imperio en el que nunca se pone el sol».',
        quotes=[Q('es_carlos1','Carlos revitalizó el concepto medieval de monarquía universal'), Q('en_carlos5','Charles revitalised the medieval concept of universal monarchy.'), Q('en_carlos5','was the first collection of realms labelled')]))
    P.append(dict(text='En 1556 Carlos aceptó la Paz de Augsburgo y abandonó su proyecto multinacional con abdicaciones que dividieron sus dominios entre los Habsburgo españoles, encabezados por su hijo Felipe II, y los Habsburgo austriacos, encabezados por su hermano Fernando. En 1557 se retiró al monasterio de Yuste, en Extremadura, donde murió un año después. La división de 1556 explica que a partir de entonces haya dos ramas de los Habsburgo y que el siguiente capítulo trate de la Monarquía Hispánica de Felipe II.',
        quotes=[Q('es_carlos1','abandonó su proyecto multinacional con abdicaciones en 1556 que dividieron sus dominios hereditarios e imperiales'), Q('en_carlos5','In 1557, Charles retired to the Monastery of Yuste in Extremadura and died there a year later.')]))
    P.append(dict(role='consejo', text='Cuando una fecha dependa de un acto (elección, coronación, abdicación), anote el acto junto con la fecha. Así evitará contradicciones aparentes, como las de su título imperial o la rendición de Toledo, y sabrá qué momento exacto documenta cada fuente.',
        quotes=[Q('es_comunidades','hasta su rendición definitiva casi un año después, el 3 de febrero de 1522'), Q('en_carlos5','Holy Roman Emperor and Archduke of Austria from 1519 to 1556')]))
    P.append(dict(role='self_check', text='¿Por qué la llegada de Carlos I a Castilla provocó recelos? ¿Qué hechos permiten decir que las Comunidades terminaron en Villalar, aunque Toledo resistiera más? ¿De qué modo financió Carlos sus guerras y qué consecuencia económica tuvo?',
        quotes=[Q('es_comunidades','Este descontento fue transmitiéndose a las capas populares'), Q('en_carlos5','which caused widespread inflation')]))
    return P

def problems(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    return [dict(role='worked', problem_type='NUMERICAL',
        prompt='Carlos reinó en España de 1516 a 1556, hizo 40 viajes por sus dominios y dedicó una cuarta parte de su reinado a viajar. Calcule cuántos años pasó viajando y cuántos meses duró, en promedio, cada viaje.',
        expected='3', quotes=[Q('es_carlos1','Sin fijar una capital, realizó 40 viajes por las diferentes entidades que gobernaba y dedicó una cuarta parte de su reinado a viajar dentro de sus reinos.'), Q('en_carlos5','With no fixed capital, he made 40 journeys through the different entities he ruled and spent a quarter of his reign travelling within his realms.')],
        method='Fracción de un periodo y reparto en partes iguales',
        solution=dict(given=[dict(symbol='a_i',value=1516,unit='dimensionless',meaning='año de inicio del reinado en España'),dict(symbol='a_f',value=1556,unit='dimensionless',meaning='año de la abdicación'),dict(symbol='f',value=0.25,unit='dimensionless',meaning='fracción del reinado dedicada a viajar'),dict(symbol='n',value=40,unit='dimensionless',meaning='número de viajes')],
          unknown='Los años de viaje totales y los meses de cada viaje en promedio.',
          model=[dict(name='Años de reinado',latex='D = a_f - a_i',symbolic='a_f-a_i'),dict(name='Años de viaje',latex='V = f\\,D',symbolic='f*(a_f-a_i)'),dict(name='Meses por viaje',latex='m = 12\\,V/n',symbolic='12*f*(a_f-a_i)/n')],
          assumptions=['Se toma el reinado de 1516 a 1556 como 40 años completos.','Se supone que los 40 viajes tuvieron la misma duración, aunque en realidad fueron muy desiguales.'],
          development=['La cuarta parte de un reinado de 40 años son 10 años; esos años se reparten entre 40 viajes.'],
          steps=[dict(text='Años de reinado',equation='D = 1556 - 1516',expression='1556-1516',expected=40,unit='dimensionless'),
                 dict(text='Años de viaje',equation='V = 0{,}25 \\cdot 40',expression='0.25*40',expected=10,unit='dimensionless'),
                 dict(text='Meses por viaje',equation='m = 12 \\cdot 10 / 40',expression='12*10/40',expected=3,unit='dimensionless')],
          result='Carlos pasó unos 10 años viajando, y cada viaje duró en promedio 3 meses.',
          interpretation='El promedio de tres meses por viaje muestra por qué Carlos gobernó desde el camino: viajar no era un paréntesis, sino una forma de gobierno.',
          limitations=['El promedio oculta viajes muy distintos: algunos duraron semanas y otros, años.'],
          mistakes=['Tomar los 40 viajes como 40 años, o confundir el reinado de 40 años con la duración total de su vida.']))]
